atabase where datname=current_database())\n            and backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.txid_current();\n        v_original_unretired:=NEW;\n        v_original_unretired.enabled:=OLD.enabled;\n        v_original_unretired.revoked_at:=OLD.revoked_at;\n        v_original_unretired.updated_at:=OLD.updated_at;\n        if v_original_authority.phase is distinct from 'RUNNING'\n          or v_original_authority.completed_step is distinct from 2\n          or v_original_authority.active_table_oid is distinct from TG_RELID\n          or v_original_authority.owner_oid is distinct from (select oid from pg_catalog.pg_roles where rolname=session_user)\n          or v_original_authority.result is not null\n          or (select count(*) from pg_catalog.jsonb_object_keys(v_original_authority.counts))<>2\n          or not (v_original_authority.counts ?& array['employee_credentials','employee_enrollment']::text[])\n          or not (coalesce(OLD.enabled,true)=true or OLD.revoked_at is null)\n          or NEW.enabled is distinct from false or NEW.revoked_at is null\n          or NEW.revoked_at < pg_catalog.transaction_timestamp() or NEW.revoked_at > pg_catalog.clock_timestamp()\n          or NEW.updated_at is distinct from OLD.updated_at\n          or pg_catalog.record_image_eq(v_original_unretired,OLD) is not true then\n          raise exception using errcode='55000',message='Original manager push retirement row differs';\n        end if;\n        if custodial_dr.immutable_original_authority_guard_matches(TG_RELID,TG_OP) is not true\n          or (select pg_catalog.to_jsonb(s) from custodial_dr.immutable_original_authority_scopes s\n            where database_oid=v_original_authority.database_oid and backend_pid=v_original_authority.backend_pid\n              and transaction_id=v_original_authority.transaction_id) is distinct from pg_catalog.to_jsonb(v_original_authority) then\n          raise exception using errcode='55000',message='Original manager push retirement scope changed';\n        end if;\n        NEW.updated_at:=pg_catalog.now();\n        return NEW;\n      end;\n    end if;\n  end if;\n  -- Exact staged original push DATA only; never a live credential grant.\n  if TG_OP = 'INSERT' and TG_LEVEL = 'ROW' and TG_WHEN = 'BEFORE'\n    and TG_TABLE_SCHEMA = 'public' and TG_TABLE_NAME = 'ops_manager_push_devices'\n    and TG_NAME = 'trg_ops_manager_push_devices_owner' and TG_NARGS = 0 then\n    if TG_RELID = pg_catalog.to_regclass('public.ops_manager_push_devices')\n      and current_user = session_user and current_user = 'postgres'\n      and pg_catalog.to_regprocedure('custodial_dr.immutable_import_matches_ordinary_record(oid,anyelement)') is not null then\n      if custodial_dr.immutable_import_matches_ordinary_record(TG_RELID,NEW) is true then\n        return NEW;\n      end if;\n    end if;\n  end if;\n -- Revocation must remain possible after authority becomes stale, including\n -- the existing restore invalidation. It cannot resurrect or reassign a row.\n IF TG_OP='UPDATE' AND TG_TABLE_NAME='ops_manager_push_devices' THEN\n  IF NOT NEW.enabled AND NEW.revoked_at IS NOT NULL AND NEW.credential_id=OLD.credential_id AND NEW.manager_id=OLD.manager_id\n  AND NEW.device_id=OLD.device_id AND NEW.fcm_token=OLD.fcm_token THEN NEW.updated_at:=now();RETURN NEW;END IF;\n END IF;\n authority:=custodial_leadership_private.notification_credential(NEW.credential_id);\n IF authority IS NULL OR authority->>'managerId' IS DISTINCT FROM NEW.manager_id::text\n OR(TG_TABLE_NAME='ops_manager_push_devices' AND authority->>'kind'='CUSTODIAL_LEADERSHIP_REGISTRATION'\n AND authority->>'deviceId' IS DISTINCT FROM to_jsonb(NEW)->>'device_id')\n THEN RAISE EXCEPTION 'Notification record must belong to its current typed manager credential' USING ERRCODE='23514';END IF;\n NEW.updated_at:=now();RETURN NEW;\nEND $function$\n","install_before_body_sha256":"87c2f2d6f401e1c4f36944e69be02678efdca6f2d13f868a51865e781caf898b","afte