N public.static_weekly_version_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\ndeclare source_comparison public.weekly_schedule_versions%rowtype;\nbegin\n  if tg_op='DELETE' then raise exception using errcode='23514',message='weekly versions are immutable'; end if;\n  if tg_op='INSERT' then\n    if new.lifecycle_state='published' and current_setting('app.static_weekly_publish_write',true) is distinct from 'on' then raise exception using errcode='23514',message='published versions require v2 publication'; end if;\n    return new;\n  end if;\n  if old.lifecycle_state='draft' and current_setting('app.static_weekly_publish_write',true)='on' and new.lifecycle_state='published' and new.revision=old.revision then return new; end if;\n  -- v3 binds a just-created v2 draft to a registered immutable source inside\n  -- the same SECURITY DEFINER transaction. No other field/revision may move.\n  if old.lifecycle_state='draft' and current_setting('app.static_weekly_source_bind',true)='on' and old.authority_source_id is null and new.authority_source_id is not null then\n    source_comparison:=new;\n    source_comparison.authority_source_id:=old.authority_source_id;\n    if source_comparison is not distinct from old then return new; end if;\n  end if;\n  if old.lifecycle_state<>'draft' or current_setting('app.static_weekly_draft_write',true) is distinct from 'on' or new.lifecycle_state<>'draft' or new.revision<>old.revision+1 then raise exception using errcode='23514',message='draft versions require a revision-checked v2 command'; end if;\n  return new;\nend\n$function$\n","install_before_body_sha256":"551476b593ecbe90ea6c7343ad4ce9275c741183210f31d8f73f665abbe38ec9","after":"CREATE OR REPLACE FUNCTION public.static_weekly_version_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\ndeclare source_comparison public.weekly_schedule_versions%rowtype;\nbegin\n  -- Exact authenticated archived INSERT only. The entire normal body follows unchanged.\n  IF TG_OP='INSERT' AND TG_LEVEL='ROW' AND TG_NARGS=0\n   AND current_user=session_user AND current_user='postgres'\n   AND ((TG_TABLE_SCHEMA='public' AND TG_TABLE_NAME='weekly_schedule_versions'\n     AND TG_NAME='trg_static_weekly_versions_guard' AND TG_WHEN='BEFORE'\n     AND TG_RELID=pg_catalog.to_regclass('public.weekly_schedule_versions'))) THEN\n   IF custodial_dr.immutable_import_matches_ordinary_record(TG_RELID,NEW) IS TRUE\n    THEN RETURN NEW; END IF;\n  END IF;\n  if tg_op='DELETE' then raise exception using errcode='23514',message='weekly versions are immutable'; end if;\n  if tg_op='INSERT' then\n    if new.lifecycle_state='published' and current_setting('app.static_weekly_publish_write',true) is distinct from 'on' then raise exception using errcode='23514',message='published versions require v2 publication'; end if;\n    return new;\n  end if;\n  if old.lifecycle_state='draft' and current_setting('app.static_weekly_publish_write',true)='on' and new.lifecycle_state='published' and new.revision=old.revision then return new; end if;\n  -- v3 binds a just-created v2 draft to a registered immutable source inside\n  -- the same SECURITY DEFINER transaction. No other field/revision may move.\n  if old.lifecycle_state='draft' and current_setting('app.static_weekly_source_bind',true)='on' and old.authority_source_id is null and new.authority_source_id is not null then\n    source_comparison:=new;\n    source_comparison.authority_source_id:=old.authority_source_id;\n    if source_comparison is not distinct from old then return new; end if;\n  end if;\n  if old.lifecycle_state<>'draft' or current_setting('app.static_weekly_draft_write',true) is distinct from 'on' or new.lifecycle_state<>'draft' or new.revision<>old.revision+1 then raise exception using errcode='23514',message='draft versions require a revision-checked v2 command'; end if;\n  return new;\nend\n$function$\n","after_body_sha256":"85417e87155fde93d1afdd0d35e625cf513cc319df041d1ff6bc9aa0a6e25022","security_definer":true,"triggers":[{"name":"trg_static_weekly_versions_guard","type":31,"when":null,"nargs":0,"table":"weekly_schedule_versions","schema":"public","columns":[],"enabled":"O","args_hex":"","internal":false,"new_table":null,"old_table":null,"constraint":false,"deferrable":false,"initially_deferred":false}]},{"identity":"public.sync_migration_log_summary()","install_before":"CREATE OR REPLACE FUNCTION public.sync_migration_log_summary()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'extensions'\nAS $function$\nbegin\n  insert into public.migration_log_summary(\n    migration_name, statement_count, total_sql_bytes, latest_sql_sha256,\n    first_applied_at, last_applied_at, last_applied_by, updated_at\n  ) values (\n    new.migration_name, 1, octet_length(new.sql_text),\n    encode(digest(new.sql_text, 'sha256'), 'hex'),\n    new.applied_at, new.applied_at, new.applied_by, now()\n  )\n  on conflict (migration_name) do update\n  set statement_count = public.migration_log_summary.statement_count + 1,\n      total_sql_bytes = public.migration_log_summary.total_sql_bytes + excluded.total_sql_bytes,\n      latest_sql_sha256 = excluded.latest_sql_sha256,\n      first_applied_at = least(public.migration_log_summary.first_applied_at, excluded.first_applied_at),\n      last_applied_at = greatest(public.migration_log_summary.last_applied_at, excluded.last_applied_at),\n      last_applied_by = excluded.last_applied_by,\n      updated_at = now();\n  return new;\nend\n$function$\n","install_before_body_sha256":"7738f42547280d08a781100a79e8a04375a38bee13d630616c40b474f09c7efe","after":"CREATE OR REPLACE FUNCTION public.sync_migration_log_summary()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'extensions'\nAS $function$\nbegin\n  -- Exact authenticated archived INSERT only. The entire normal body follows unchanged.\n  IF TG_OP='INSERT' AND TG_LEVEL='ROW' AND TG_NARGS=0\n   AND current_user=session_user AND current_user='postgres'\n   AND ((TG_TABLE_SCHEMA='public' AND TG_TABLE_NAME='migration_log'\n     AND TG_NAME='trg_sync_migration_log_summary' AND TG_WHEN='AFTER'\n     AND TG_RELID=pg_catalog.to_regclass('public.migration_log'))) THEN\n   IF custodial_dr.immutable_import_matches_ordinary_record(TG_RELID,NEW) IS TRUE\n    THEN RETURN NEW; END IF;\n  END IF;\n  insert into public.migration_log_summary(\n    migration_name, statement_count, total_sql_bytes, latest_sql_sha256,\n    first_applied_at, last_applied_at, last_applied_by, updated_at\n  ) values (\n    new.migration_name, 1, octet_length(new.sql_text),\n    encode(digest(new.sql_text, 'sha256'), 'hex'),\n    new.applied_at, new.applied_at, new.applied_by, now()\n  )\n  on conflict (migration_name) do update\n  set statement_count = public.migration_log_summary.statement_count + 1,\n      total_sql_bytes = public.migration_log_summary.total_sql_bytes + excluded.total_sql_bytes,\n      latest_sql_sha256 = excluded.latest_sql_sha256,\n      first_applied_at = least(public.migration_log_summary.first_applied_at, excluded.first_applied_at),\n      last_applied_at = greatest(public.migration_log_summary.last_applied_at, excluded.last_applied_at),\n      last_applied_by = excluded.last_applied_by,\n      updated_at = now();\n  return new;\nend\n$function$\n","after_body_sha256":"94e57e1aab839246cb26cec855193fc98c1169933ed48bede4d15f976a1b8f0a","security_definer":true,"triggers":[{"name":"trg_sync_migration_log_summary","type":5,"when":null,"nargs":0,"table":"migration_log","schema":"public","columns":[],"enabled":"O","args_hex":"","internal":false,"new_table":null,"old_table":null,"constraint":false,"deferrable":false,"initially_deferred":false}]}]$current_original_guard_profiles$::jsonb;
 p jsonb;relation record;original pg_catalog.pg_proc%rowtype;after_row pg_catalog.pg_proc%rowtype;
 original_triggers jsonb;after_triggers jsonb;normalized_triggers jsonb;nonempty boolean;
BEGIN
 PERFORM custodial_dr.immutable_import_owner_fence();
 IF current_user<>session_user OR current_user<>'postgres' THEN RAISE EXCEPTION 'Exact isolated original cohort owner required';END IF;
 FOR relation IN SELECT DISTINCT t->>'schema' schema_name,t->>'table' table_name FROM jsonb_array_elements(profiles) f
  CROSS JOIN LATERAL jsonb_array_elements(f->'triggers') t ORDER BY schema_name,table_name LOOP
  EXECUTE format('LOCK TABLE %I.%I IN ACCESS EXCLUSIVE MODE',relation.schema_name,relation.table_name);
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM ONLY %I.%I)',relation.schema_name,relation.table_name) INTO nonempty;
  IF nonempty THEN RAISE EXCEPTION 'Original cohort requires fresh DATA';END IF;
 END LOOP;
 FOR p IN SELECT v FROM jsonb_array_elements(profiles) v LOOP
  SELECT * INTO STRICT original FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(p->>'identity');
  SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid),jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'type',t.tgtype,'enabled',t.tgenabled,
 'internal',t.tgisinternal,'constraint',t.tgconstraint<>0,'deferrable',t.tgdeferrable,'initially_deferred',t.tginitdeferred,
 'when',pg_get_expr(t.tgqual,t.tgrelid),'nargs',t.tgnargs,'args_hex',encode(t.tgargs,'hex'),'old_table',t.tgoldtable,'new_table',t.tgnewtable,
 'columns',coalesce((SELECT jsonb_agg(a.attname ORDER BY cols.ord) FROM unnest(t.tgattr::smallint[]) WITH ORDINALITY cols(attnum,ord)
  JOIN pg_catalog.pg_attribute a ON a.attrelid=t.tgrelid AND a.attnum=cols.attnum AND NOT a.attisdropped),'[]'::jsonb)) ORDER BY n.nspname,c.relname,t.tgname)
   INTO original_triggers,normalized_triggers FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid
   JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE t.tgfoid=original.oid;
  IF original.proowner<>(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=session_user)
   OR original.prokind<>'f' OR original.pronargs<>0 OR original.proargtypes<>''::oidvector
   OR original.prorettype<>'pg_catalog.trigger'::regtype OR original.proretset
   OR original.prosecdef IS DISTINCT FROM (p->>'security_definer')::boolean
   OR pg_get_functiondef(original.oid) IS DISTINCT FROM p->>'install_before'
   OR public.static_weekly_digest_text(original.prosrc) IS DISTINCT FROM p->>'install_before_body_sha256'
   OR normalized_triggers IS DISTINCT FROM p->'triggers'
  THEN RAISE EXCEPTION 'Exact original cohort Source or consumers differ';END IF;
  EXECUTE p->>'after';
  SELECT * INTO STRICT after_row FROM pg_catalog.pg_proc WHERE oid=original.oid;
  SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) INTO after_triggers FROM pg_catalog.pg_trigger t WHERE t.tgfoid=original.oid;
  IF pg_get_functiondef(after_row.oid) IS DISTINCT FROM p->>'after'
   OR public.static_weekly_digest_text(after_row.prosrc) IS DISTINCT FROM p->>'after_body_sha256'
   OR to_jsonb(after_row)-'prosrc' IS DISTINCT FROM to_jsonb(original)-'prosrc'
   OR after_triggers IS DISTINCT FROM original_triggers
  THEN RAISE EXCEPTION 'Original cohort metadata changed outside exact branch';END IF;
 END LOOP;
 PERFORM custodial_dr.immutable_import_owner_fence();
END $current_original_guard_cohort_install$;
